export function deckLegalityCardFor(printingId: string): ResolvedDeckCard | undefined {
  const entry = DECK_LEGALITY_CATALOG[printingId as keyof typeof DECK_LEGALITY_CATALOG];
  return entry ? { printingId, officialId: entry[0], kind: entry[1], deckLimit: entry[2] } : undefined;
}

export const deckLegalityCatalogResolver: DeckCardResolver = deckLegalityCardFor;
